const normalizeTextOverlayEffect = (value: unknown): TextOverlayEffect => {
  const effect = String(value ?? "none");
  return TEXT_OVERLAY_EFFECT_OPTIONS.some((option) => option.value === effect)
    ? effect as TextOverlayEffect
    : "none";
};

